 Creating a complex smart contract involves writing code that follows a specific programming language, such as Solidity for Ethereum, and adheres to the Ethereum Virtual Machine (EVM) architecture. A smart contract is a self-executing contract with the terms of the agreement directly written into code, which is stored on the blockchain.

Here's an example of a complex smart contract that includes multiple functions, events, and modifiers. This contract is a simple crowdfunding platform where users can contribute Ether to a project and receive tokens in return.

```solidity
pragma solidity ^0.8.0;

contract Crowdfunding {
    struct Contribution {
        address contributor;
        uint256 amount;
        uint256 tokenAmount;
    }

    mapping(address => bool) public isContributor;
    mapping(address => uint256) public contributorTokens;
    mapping(address => Contribution[]) public contributions;
    uint256 public totalContributed;
    uint256 public goal;
    uint256 public tokensPerEther;
    uint256 public tokensSold;

    event ContributionReceived(address indexed contributor, uint256 indexed tokenAmount);

    modifier onlyContributor() {
        require(isContributor[msg.sender], "You must be a contributor to call this function.");
        _;
    }

    constructor(uint256 _goal, uint256 _tokensPerEther) public payable {
        goal = _goal;
        tokensPerEther = _tokensPerEther;
    }

    function contribute() public payable {
        totalContributed += msg.value;
        Contribution memory newContribution = Contribution({
            contributor: msg.sender,
            amount: msg.value,
            tokenAmount: 0
        });
        contributions[msg.sender].push(newContribution);
        if (totalContributed >= goal) {
            sellTokens();
        }
        emit ContributionReceived(msg.sender, newContribution.tokenAmount);
    }

    function sellTokens() private {
        uint256 tokensToSell = goal - totalContributed;
        uint256 etherPerToken = tokensPerEther * (1 ether);
        for (uint256 i = 0; i < contributions.length; i++) {
            Contribution[] memory contributionsForAddress = contributions[i];
            for (uint256 j = 0; j < contributionsForAddress.length; j++) {
                Contribution memory contribution = contributionsForAddress[j];
                contribution.tokenAmount = contribution.amount * tokensPerEther;
                contribution.tokenAmount = contribution.tokenAmount * (tokensToSell / totalContributed);
                contributorTokens[contribution.contributor] += contribution.tokenAmount;
                totalContributed -= contribution.amount;
                tokensSold += contribution.tokenAmount;
            }
        }
    }

    function getTokens() public {
        require(isContributor[msg.sender], "You must be a contributor to call this function.");
        require(contributorTokens[msg.sender] > 0, "You have no tokens to claim.");
        msg.sender.transfer(contributorTokens[msg.sender]);
        contributorTokens[msg.sender] = 0;
    }

    function isCompleted() public view returns (bool) {
        return totalContributed >= goal;
    }
}
```

This smart contract allows users to contribute Ether to a project, receive tokens in return, and claim their tokens once the project is funded. The contract also includes a modifier to ensure that only contributors can call certain functions, and events to log contributions.

