import java.util.function.Function;
import java.util.stream.Collectors;

public Pair<Integer, String> getMostPopularCarColor(List<Car> cars) {
    Map<String, Integer> carColorCount = new HashMap<>();

    for (Car car : cars) {
        if (carColorCount.containsKey(car.getColor())) {
